import Foundation

// Java 8 semantics, verified against JDK 8 goldens
// (Tests/Fixtures/java8, generated by scripts/golden/gen.sh).

public enum JavaDouble {
    /// Java 8 `Double.toString(double)`: "271.0", "1.0E-4", "NaN", "Infinity", "-0.0".
    public static func string(_ value: Double) -> String { JavaDoubleFormatter.string(value) }
    /// Java `Double.parseDouble` after `trim()`; also accepts "," as decimal point (server TURN),
    /// and trailing d/D/f/F. Returns nil where Java throws NumberFormatException.
    public static func parse(_ text: String, allowComma: Bool = false) -> Double? {
        JavaDoubleParser.parse(allowComma ? text.replacingOccurrences(of: ",", with: ".") : text)
    }
}

public enum JavaString {
    /// Java `String.split(literal)` with limit 0: trailing empty strings removed. `limit > 0` behaves like Java.
    /// Works on UTF-16 units, so "\r\n" is never treated as one character.
    public static func split(_ s: String, separator: Character, limit: Int = 0) -> [String] {
        let sep = Array(separator.utf16)
        let units = Array(s.utf16)
        guard !sep.isEmpty else { return [s] }
        var parts: [String] = []
        var off = 0
        var i = 0
        let limited = limit > 0
        var matched = false
        while i + sep.count <= units.count {
            if units[i] == sep[0] && (sep.count == 1 || Array(units[i..<(i + sep.count)]) == sep) {
                matched = true
                if !limited || parts.count < limit - 1 {
                    parts.append(String(decoding: units[off..<i], as: UTF16.self))
                    off = i + sep.count
                    i = off
                    continue
                }
                break
            }
            i += 1
        }
        if !matched { return [s] }
        // The last element takes the rest of the string (parts.count <= limit - 1 here when limited).
        parts.append(String(decoding: units[off...], as: UTF16.self))
        if limit == 0 {
            while let last = parts.last, last.isEmpty { parts.removeLast() }
        }
        return parts
    }

    /// Java `String.trim()`: strips every char <= U+0020 at both ends.
    public static func trim(_ s: String) -> String {
        let units = Array(s.utf16)
        var lo = 0, hi = units.count
        while lo < hi && units[lo] <= 0x20 { lo += 1 }
        while hi > lo && units[hi - 1] <= 0x20 { hi -= 1 }
        if lo == 0 && hi == units.count { return s }
        return String(decoding: units[lo..<hi], as: UTF16.self)
    }

    /// Java `Boolean.parseBoolean`: true iff equalsIgnoreCase("true").
    public static func parseBool(_ s: String) -> Bool { s.lowercased() == "true" }

    /// Java `String.startsWith` (UTF-16 prefix, no grapheme clustering).
    public static func startsWith(_ s: String, _ prefix: String) -> Bool {
        var it = s.utf16.makeIterator()
        for p in prefix.utf16 {
            guard let c = it.next(), c == p else { return false }
        }
        return true
    }

    /// Java `Integer.parseInt` / `Integer.valueOf` (decimal, optional sign, 32-bit range, no whitespace).
    public static func parseInt(_ s: String) -> Int? {
        guard s.utf8.allSatisfy({ ($0 >= 0x30 && $0 <= 0x39) || $0 == 0x2B || $0 == 0x2D }) else { return nil }
        guard let v = Int32(s) else { return nil }
        return Int(v)
    }
}

/// CP1252 with Java 8 semantics (undefined bytes decode to U+FFFD; unmappable chars encode as "?").
public enum Windows1252 {
    /// 0x80...0x9F → Unicode (Java Cp1252: the five undefined slots map to U+FFFD).
    static let high: [UInt16] = [
        0x20AC, 0xFFFD, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021,
        0x02C6, 0x2030, 0x0160, 0x2039, 0x0152, 0xFFFD, 0x017D, 0xFFFD,
        0xFFFD, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022, 0x2013, 0x2014,
        0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0xFFFD, 0x017E, 0x0178,
    ]
    /// Full 256-entry decode table.
    static let table: [UInt16] = (0..<256).map { b in
        (0x80...0x9F).contains(b) ? high[b - 0x80] : UInt16(b)
    }
    static let reverse: [UInt32: UInt8] = {
        var r: [UInt32: UInt8] = [:]
        for (i, u) in high.enumerated() where u != 0xFFFD { r[UInt32(u)] = UInt8(0x80 + i) }
        return r
    }()

    public static func encode(_ s: String) -> [UInt8] {
        var out: [UInt8] = []
        out.reserveCapacity(s.utf8.count)
        for scalar in s.unicodeScalars {
            let v = scalar.value
            if v < 0x80 || (v >= 0xA0 && v <= 0xFF) {
                out.append(UInt8(v))
            } else if let b = reverse[v] {
                out.append(b)
            } else {
                out.append(0x3F) // Java: unmappable → '?' (C1 controls U+0080…U+009F included)
            }
        }
        return out
    }

    public static func decode(_ bytes: some Sequence<UInt8>) -> String {
        var units: [UInt16] = []
        units.reserveCapacity(bytes.underestimatedCount)
        for b in bytes { units.append(table[Int(b)]) }
        return String(decoding: units, as: UTF16.self)
    }
}

/// java.util.Properties-compatible document (load/store), preserving key order and unknown keys.
public struct JavaProperties: Sendable, Equatable {
    public private(set) var keys: [String] = []
    private var values: [String: String] = [:]
    public init() {}

    public subscript(key: String) -> String? {
        get { values[key] }
        set {
            if let newValue {
                if values[key] == nil { keys.append(key) }
                values[key] = newValue
            } else if values.removeValue(forKey: key) != nil {
                keys.removeAll { $0 == key }
            }
        }
    }

    /// Parses `Properties.load` text (ISO-8859-1 + \uXXXX escapes, `#`/`!` comments, `=`/`:`/space separators, continuations).
    /// Like Java, a malformed `\uXXXX` stops loading; entries read before it are kept.
    public static func parse(_ data: Data) -> JavaProperties {
        var p = JavaProperties()
        for (k, v) in JavaPropertiesCodec.load(data) { p[k] = v }
        return p
    }

    /// Serialises like `Properties.store(out, comment)`: comment line, `#<date>` line, escaped `key=value` lines,
    /// in this document's key order. Lines end with "\n" (Java's loader accepts any terminator).
    public func serialized(comment: String?, date: Date = Date()) -> Data {
        JavaPropertiesCodec.store(keys.map { ($0, values[$0] ?? "") }, comment: comment, date: date, timeZone: .current)
    }
}

/// java.net.URLEncoder / URLDecoder with UTF-8 (used for `switchstate<name>.properties` and DeviceManager names).
public enum JavaURLCoding {
    public static func encode(_ s: String) -> String {
        var out = ""
        for b in s.utf8 {
            switch b {
            case UInt8(ascii: "a")...UInt8(ascii: "z"), UInt8(ascii: "A")...UInt8(ascii: "Z"),
                 UInt8(ascii: "0")...UInt8(ascii: "9"), UInt8(ascii: "."), UInt8(ascii: "-"),
                 UInt8(ascii: "*"), UInt8(ascii: "_"):
                out.unicodeScalars.append(Unicode.Scalar(b))
            case UInt8(ascii: " "):
                out += "+"
            default:
                out += String(format: "%%%02X", b)
            }
        }
        return out
    }

    /// Java decodes runs of `%XX` as UTF-8 (malformed → U+FFFD) and `+` as space. Where Java would
    /// throw (bad or truncated `%` escape) the offending text is kept literally instead.
    public static func decode(_ s: String) -> String {
        let bytes = Array(s.utf8)
        var out = ""
        var escaped: [UInt8] = []
        var literal: [UInt8] = []
        func flushEscaped() {
            if !escaped.isEmpty { out += String(decoding: escaped, as: UTF8.self); escaped.removeAll() }
        }
        func flushLiteral() {
            if !literal.isEmpty { out += String(decoding: literal, as: UTF8.self); literal.removeAll() }
        }
        func hexValue(_ c: UInt8) -> UInt8? {
            switch c {
            case 0x30...0x39: c - 0x30
            case 0x41...0x46: c - 0x41 + 10
            case 0x61...0x66: c - 0x61 + 10
            default: nil
            }
        }
        var i = 0
        while i < bytes.count {
            let c = bytes[i]
            if c == UInt8(ascii: "%"), i + 2 < bytes.count,
               let h = hexValue(bytes[i + 1]), let l = hexValue(bytes[i + 2]) {
                flushLiteral()
                escaped.append(h << 4 | l)
                i += 3
                continue
            }
            flushEscaped()
            literal.append(c == UInt8(ascii: "+") ? UInt8(ascii: " ") : c)
            i += 1
        }
        flushEscaped()
        flushLiteral()
        return out
    }
}
